import React, { useState, useEffect } from 'react';
import './Jubilacion.css'; 
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

const Jubilacion = () => {
    const [data, setData] = useState([]);  
    const [loading, setLoading] = useState(true);  
    const [error, setError] = useState(null);  // Estado para manejar errores
    const apiKey = process.env.REACT_APP_API_KEY;  // Usa variables de entorno

    const fetchExchangeRateData = async () => {
        try {
            const response = await fetch(
                `https://api.fastforex.io/time-series?from=USD&to=MXN&interval=P1D&api_key=${apiKey}`
            );
            const result = await response.json();

            const transformedData = Object.keys(result.results.MXN).map(date => ({
                date: date,
                value: result.results.MXN[date],
            }));

            setData(transformedData);  
            setLoading(false);  
        } catch (error) {
            console.error('Error fetching exchange rate data:', error);
            setError('Error al cargar los datos.');  // Mensaje de error
            setLoading(false);  
        }
    };

    useEffect(() => {
        fetchExchangeRateData();
    }, []);

    return (
        <div className="jubilacion-container">
            <h1 className="jubilacion-title">Predicción de Moneda</h1>
            <div className="jubilacion-content">
                <p>Este gráfico muestra el precio del dólar frente al peso mexicano (MXN).</p>

                {loading ? (
                    <p>Cargando datos...</p>
                ) : (
                    <>
                        {error && <p>{error}</p>}  {/* Mostrar mensaje de error */}
                        <ResponsiveContainer width="100%" height={400}>
                            <LineChart data={data}>
                                <CartesianGrid strokeDasharray="3 3" />
                                <XAxis dataKey="date" />
                                <YAxis ticks={[12, 18, 24]} domain={[12, 24]} />
                                <Tooltip />
                                <Line type="monotone" dataKey="value" stroke="#007bff" />
                            </LineChart>
                        </ResponsiveContainer>
                    </>
                )}
            </div>
        </div>
    );
};

export default Jubilacion;
